cd /tmp/wt-main-ross && python3 - <<'EOF'
import re
for f in ["S04/E15.md","S04/E16.md","S04/E17.md","S04/E18.md","S04/E19.md","S04/E20.md","S04/E21.md","S04/E22.md","S04/E23.md","S04/E24.md","S04/E25.md"]:
    t=open(f).read()
    for m in re.finditer(r'^(\w+): \((.*?)\) (.*)$', t, re.M):
        s=m.group(3)
        if re.search(r'landlord|ninety days|renew|Gus|lease|notice one|deadline', s, re.I):
            print(f, m.group(1), "|", s[:220]); print()
EOF

cd /tmp/wt-main-ross && python3 - <<'EOF'
import re, glob
pat = re.compile(r'\b(landlord|ninety|renew|Gus|deadline|March)\b', re.I)
for f in sorted(glob.glob("S04/E*.md")):
    t=open(f).read()
    for m in re.finditer(r'^(\w+): \((.*?)\) (.*)$', t, re.M):
        if pat.search(m.group(3)):
            print(f.split('/')[-1], m.group(1), "|", m.group(3)[:200]); print()
EOF

